/// Case-insensitive keyword lookup (`HtmlName::Lookup`).
#[must_use]
pub fn lookup(name: &[u8]) -> Keyword {
    // Stack-lowercase short names; heap fallback for long ones.
    let mut buf = [0u8; 64];
    let lowered: &[u8] = if name.len() <= buf.len() {
        for (slot, byte) in buf.iter_mut().zip(name.iter()) {
            *slot = byte.to_ascii_lowercase();
        }
        &buf[..name.len()]
    } else {
        return lookup_heap(name);
    };
    match LOOKUP.binary_search_by(|entry| entry.0.as_bytes().cmp(lowered)) {
        Ok(index) => LOOKUP[index].2,
        Err(_) => Keyword::NotAKeyword,
    }
}

fn lookup_heap(name: &[u8]) -> Keyword {
    let lowered: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
    match LOOKUP.binary_search_by(|entry| entry.0.as_bytes().cmp(&lowered)) {
        Ok(index) => LOOKUP[index].2,
        Err(_) => Keyword::NotAKeyword,
    }
}

